// Checkout conversion fix: ensure paidEvents increment on successful payment
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);
const { logRevenueEvent } = require('./revenueTracker');

module.exports = async function handleCheckoutSessionCompleted(session) {
  if (session.payment_status === 'paid') {
    await logRevenueEvent({
      type: 'paid_event',
      amount: session.amount_total,
      currency: session.currency,
      customer: session.customer,
      timestamp: new Date().toISOString()
    });
    console.log('Checkout conversion: paid event logged');
  }
};
